import json
import os
import sys
import tempfile


def main():
    if len(sys.argv) != 2:
        print("usage: probe.py <directory>", file=sys.stderr)
        return 1

    directory = sys.argv[1]
    output_path = os.path.join(os.getcwd(), "summary.json")

    if os.path.exists(output_path):
        print(f"refusing to run: {output_path} already exists", file=sys.stderr)
        return 1

    try:
        entries = sorted(os.listdir(directory))
    except OSError as exc:
        print(f"cannot list directory {directory}: {exc}", file=sys.stderr)
        return 1

    values = []
    for name in entries:
        if not name.endswith(".json"):
            continue
        full_path = os.path.join(directory, name)
        if not os.path.isfile(full_path):
            continue

        try:
            with open(full_path, "r", encoding="utf-8") as handle:
                data = json.load(handle)
        except (OSError, json.JSONDecodeError) as exc:
            print(f"skipping {full_path}: {exc}", file=sys.stderr)
            continue

        if not isinstance(data, dict) or "cost_usd" not in data:
            continue

        value = data["cost_usd"]
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            print(f"skipping {full_path}: cost_usd is not numeric", file=sys.stderr)
            continue

        values.append(value)

    total = sum(values) if values else 0
    mean = (total / len(values)) if values else None

    summary = {"total": total, "mean": mean}

    output_dir = os.path.dirname(output_path) or "."
    fd, temp_path = tempfile.mkstemp(prefix=".summary.json.", dir=output_dir)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            json.dump(summary, handle)
        os.replace(temp_path, output_path)
    except BaseException:
        os.remove(temp_path)
        raise

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
